package com.powercms.cms.sitepackage;
import com.fasterxml.jackson.databind.*; import com.powercms.common.error.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CssClassService { public static final int MAX_CLASSES=500,MAX_LENGTH=64; private final TemplateService templates; private final ObjectMapper mapper; public CssClassService(TemplateService t,ObjectMapper m){templates=t;mapper=m;} public record Result(List<String> classes,List<String>warnings){} public Result load(UUID projectId,boolean preview){try{String raw=templates.readFileContent(projectId,"templates/classes.json");JsonNode n=mapper.readTree(raw);if(!n.isObject()||!n.path("classes").isArray())return new Result(List.of(),List.of("classes.json must be {classes:[]}"));LinkedHashSet<String> out=new LinkedHashSet<>();for(JsonNode x:n.path("classes")){String v=x.asText();if(v.matches("[A-Za-z0-9-]{1,"+MAX_LENGTH+"}")&&out.size()<MAX_CLASSES)out.add(v);}return new Result(List.copyOf(out),List.of());}catch(Exception e){return new Result(List.of(),List.of("invalid classes.json; page rendering continues"));}} public String normalize(Object raw){if(raw==null)return "";StringBuilder b=new StringBuilder();for(String v:String.valueOf(raw).trim().split("\\s+")){if(v.matches("[A-Za-z0-9-]{1,"+MAX_LENGTH+"}")){if(b.length()>0)b.append(' ');b.append(v);}}return b.toString();} }
